exercises.solution:
const donnees = document.querySelector("#app").dataset;
const restantes = Number(donnees.capacite) - Number(donnees.inscrits);
function App() { return <article id="fiche" className="atelier"><h1 id="titre">{donnees.titre}</h1><p id="disponibles">{restantes} places restantes</p><button id="consulter" type="button" disabled={restantes === 0}>Consulter</button></article>; }
root.render(<App />);

